import hashlib
import json
from functools import lru_cache
from pathlib import Path
import subprocess
import sys
import unicodedata
from urllib.request import urlopen

manifest_file, destination, route, *repo_arg = sys.argv[1:]
if route not in {"primary", "public", "archive"}:
    raise ValueError("route must be primary, public or archive")
manifest = json.loads(Path(manifest_file).read_text(encoding="utf-8"))
repo = Path(repo_arg[0]) if repo_arg else Path(".")
digest = lambda data: hashlib.sha256(data).hexdigest()

@lru_cache(None)
def source_view(key):
    source = manifest["sources"][key]
    if "git_path" in source:
        obj = source["git_commit"] + ":" + source["git_path"]
        raw = subprocess.check_output(["git", "-C", str(repo), "show", obj])
    else:
        for url in source["download_urls"]:
            try:
                with urlopen(url, timeout=25) as response:
                    raw = response.read()
            except OSError:
                continue
            if digest(raw) == source["raw_sha256"]:
                break
        else:
            raise ValueError("could not fetch pinned bytes for " + key)
    if digest(raw) != source["raw_sha256"]:
        raise ValueError("source checksum mismatch: " + key)
    transform = source["transform"]
    if transform == "identity":
        text = raw.decode("utf-8")
    else:
        text = " ".join(raw.decode("utf-8-sig").split())
        text = unicodedata.normalize("NFKC", text)
        table = str.maketrans(manifest["normalization"]["punctuation"])
        text = text.translate(table).lower()
        if transform == "book_archive_double_dash":
            text = text.replace("--", "-")
        elif transform != "book":
            raise ValueError("unknown transform: " + transform)
    if len(text) != source["view_codepoints"] or digest(text.encode("utf-8")) != source["view_sha256"]:
        raise ValueError("normalized source checksum mismatch: " + key)
    return text

out = Path(destination)
out.mkdir(parents=True, exist_ok=True)
for card in manifest["cards"]:
    parts = []
    for half in card["halves"]:
        locations = half["locations"]
        loc = locations.get(route, locations["primary"])
        start, end = loc["codepoints"]
        part = source_view(loc["source"])[start:end]
        if len(part) != 2048 or digest(part.encode("utf-8")) != half["sha256"]:
            raise ValueError("half mismatch: " + card["file"] + "/" + half["side"])
        parts.append(part)
    data = "".join(parts).encode("utf-8")
    if len(data) != card["utf8_bytes"] or digest(data) != card["sha256"]:
        raise ValueError("page mismatch: " + card["file"])
    (out / card["file"]).write_bytes(data)
    print(card["sha256"], card["file"])
